sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.searchQuery = '';
    c.selectedDept = '';
};

sp_widget.css:
.aegis-jobs-page{
  max-width:1400px;
  margin:auto;
  padding-bottom:80px;
  background:#f7f2e8;
}

/* HERO */

.hero-section{
  position:relative;
  overflow:hidden;
  border-radius:40px;
  padding:70px;
  background:
  linear-gradient(
    135deg,
    #032f26 0%,
    #014235 100%
  );
}

.hero-content{
  position:relative;
  z-index:2;
  max-width:700px;
}

.hero-tag{
  color:#fff;
  font-size:18px;
  font-weight:600;
  margin-bottom:25px;
}

.hero-tag .dot{
  width:12px;
  height:12px;
  background:#e4ab39;
  display:inline-block;
  border-radius:50%;
  margin-right:10px;
}

.hero-section h1{
  color:white;
  font-size:72px;
  line-height:1.05;
  font-weight:800;
}

.hero-section h1 span{
  color:#e4ab39;
}

.hero-section p{
  color:#d6e3dd;
  font-size:22px;
  line-height:1.8;
  margin-top:25px;
}

.hero-stats{
  display:flex;
  gap:20px;
  margin-top:40px;
}

.stat-card{
  background:rgba(255,255,255,.08);
  backdrop-filter:blur(10px);
  border-radius:20px;
  padding:18px 28px;
}

.stat-card h3{
  color:white;
  font-size:30px;
  margin:0;
}

.stat-card span{
  color:#c7d7cf;
}

.hero-blob-1{
  position:absolute;
  width:420px;
  height:420px;
  border-radius:50%;
  background:#d96b47;
  right:-100px;
  top:-40px;
  opacity:.95;
}

.hero-blob-2{
  position:absolute;
  width:220px;
  height:220px;
  border-radius:50%;
  background:#e4ab39;
  right:300px;
  bottom:-80px;
}

/* FILTERS */

.filter-bar{
  margin-top:-35px;
  position:relative;
  z-index:5;

  display:flex;
  gap:20px;

  padding:25px;
  background:white;
  border-radius:28px;

  box-shadow:
    0 15px 35px rgba(0,0,0,.08);
}

.search-box{
  flex:1;
  display:flex;
  align-items:center;
  gap:10px;
}

.search-box input{
  width:100%;
  border:none;
  outline:none;
  font-size:16px;
}

.filter-bar select{
  width:240px;
  border:none;
  background:#f7f2e8;
  border-radius:16px;
  padding:14px;
}

/* SECTION */

.section-title{
  margin:60px 0 30px;
  display:flex;
  justify-content:space-between;
  align-items:center;
}

.section-title h2{
  font-size:42px;
  color:#032f26;
}

.role-count{
  background:white;
  padding:14px 22px;
  border-radius:999px;
  font-weight:700;
}

/* JOBS */

.job-grid{
  display:grid;
  grid-template-columns:
    repeat(auto-fill,minmax(340px,1fr));
  gap:24px;
}

.job-card{
  background:white;
  border-radius:30px;
  padding:28px;

  box-shadow:
    0 10px 30px rgba(0,0,0,.06);

  transition:.3s;
}

.job-card:hover{
  transform:translateY(-8px);
}

.card-top{
  display:flex;
  justify-content:space-between;
  margin-bottom:25px;
}

.dept-icon{
  width:58px;
  height:58px;
  border-radius:18px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:white;
  font-weight:700;
  font-size:22px;

  background:
  linear-gradient(
      135deg,
      #032f26,
      #014235
  );
}

.level-badge{
  background:#f7f2e8;
  padding:10px 16px;
  border-radius:999px;
  font-weight:700;
}

.job-main h3{
  font-size:28px;
  color:#032f26;
  margin-bottom:12px;
}

.job-meta{
  color:#6b7280;
}

.skills{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin:22px 0;
}

.skill-pill{
  background:#f7f2e8;
  padding:8px 14px;
  border-radius:999px;
  font-size:13px;
}

.card-bottom{
  display:flex;
  justify-content:space-between;
  align-items:center;
}

.view-role{
  color:#d96b47;
  font-weight:700;
  text-decoration:none;
}

sp_widget.script:
(function() {
    data.jobs = [];
    var gr = new GlideRecord('x_snc_aegis_job_requisition');
    gr.addQuery('status', 'PUBLISHED');
    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {
        var rawSkills = gr.getValue('required_skills') || '';
        data.jobs.push({
            sys_id: gr.getUniqueValue(),
            role_title: gr.getValue('role_title') || '',
            department: gr.getValue('department') || '',
            level: gr.getValue('level') || '',
            experience_required_years: gr.getValue('experience_required_years') || '0',
            required_skills: rawSkills,
            skills_array: rawSkills.split(',').map(function(s) { return s.trim(); }).filter(function(s){ return s; })
        });
    }
})();
